package com.bitedash.dto; import com.bitedash.entity.*; public record RestaurantResponse(Long id,String name,String cuisine,String address,String imageUrl,java.math.BigDecimal rating,String deliveryMinutes){public static RestaurantResponse of(Restaurant r){return new RestaurantResponse(r.getId(),r.getName(),r.getCuisine(),r.getAddress(),r.getImageUrl(),r.getRating(),r.getDeliveryMinutes());}}
